/** Timetable editing and portable files, scoped to the current school identity. */
public final class TimetableTools {
    private final Activity a;private final Runnable refresh;private final TimetableRepository repo;
    public static final int RESTORE=401,WALLPAPER=402,EXPORT=403;
    private String pendingExport;
    public TimetableTools(Activity activity,Runnable refresh){a=activity;this.refresh=refresh;repo=new TimetableRepository(a);}
    private int dp(int n){return CampusUi.dp(a,n);}
    private void error(Exception e){new AlertDialog.Builder(a).setTitle("暂未完成").setMessage(e.getMessage()==null?"请检查输入后重试":e.getMessage()).setPositiveButton("知道了",null).show();}
    private LinearLayout form(){LinearLayout v=CampusUi.column(a);v.setPadding(dp(22),dp(8),dp(22),dp(12));return v;}
    private EditText field(LinearLayout parent,String label,String value,String hint){TextView title=CampusUi.text(a,label,12,CampusUi.MUTED);title.setPadding(0,dp(12),0,dp(4));parent.addView(title);EditText input=new EditText(a);input.setTextSize(15);input.setTextColor(CampusUi.INK);input.setText(value);input.setHint(hint);input.setSingleLine(true);parent.addView(input);return input;}
    private Spinner spinner(LinearLayout form,String title,String[] labels,int selected){TextView text=CampusUi.text(a,title,12,CampusUi.MUTED);text.setPadding(0,dp(13),0,dp(5));form.addView(text);Spinner s=new Spinner(a);s.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,labels));s.setSelection(Math.max(0,Math.min(labels.length-1,selected)));form.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));return s;}
    private AlertDialog dialog(String title,LinearLayout form,String action,Save save){ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog d=new AlertDialog.Builder(a).setTitle(title).setView(scroll).setNegativeButton("取消",null).setPositiveButton(action,null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(button->{try{save.run();d.dismiss();refresh.run();}catch(Exception e){error(e);}}));d.show();return d;}
    private interface Save{void run()throws Exception;}
    private void save(JSONObject doc)throws Exception{repo.save(doc);}
    public void semesters(){try{JSONArray docs=repo.semesters();String[] names=new String[docs.length()+1];for(int i=0;i<docs.length();i++)names[i]=docs.getJSONObject(i).optString("semester","未命名学期");names[names.length-1]="＋ 新建学期";new AlertDialog.Builder(a).setTitle("我的学期").setItems(names,(d,i)->{try{if(i==docs.length())newSemester();else{JSONObject doc=docs.getJSONObject(i);new AlertDialog.Builder(a).setTitle(doc.optString("semester")).setItems(new String[]{"切换到此学期","重命名","删除此学期"},(x,w)->{try{if(w==0){repo.select(doc.getString("timetableId"));refresh.run();}if(w==1){LinearLayout f=form();EditText name=field(f,"学期名称",doc.optString("semester"),"请输入名称");dialog("重命名学期",f,"保存",()->{String value=name.getText().toString().trim();if(value.isEmpty())throw new IllegalArgumentException("请输入学期名称");JSONObject existing=repo.findSemester(value);if(existing!=null&&!existing.optString("timetableId").equals(doc.optString("timetableId")))throw new IllegalArgumentException("该名称已被其他学期使用");doc.put("semester",value);save(doc);});}if(w==2)new AlertDialog.Builder(a).setTitle("删除此学期？").setMessage("此学期的本机课程、调课记录和设置将被删除。").setNegativeButton("取消",null).setPositiveButton("删除",(q,z)->{repo.delete(doc.optString("timetableId"));refresh.run();}).show();}catch(Exception e){error(e);}}).show();}}catch(Exception e){error(e);}}).setNegativeButton("关闭",null).show();}catch(Exception e){error(e);}}
    public void newSemester(){LinearLayout f=form();EditText name=field(f,"学期名称","","如：2026–2027 第一学期");EditText date=field(f,"第一教学周周一（可稍后设置）","","YYYY-MM-DD");EditText weeks=field(f,"教学周数","20","1–60");weeks.setInputType(2);dialog("新建学期",f,"创建",()->{String value=name.getText().toString().trim();if(value.isEmpty())throw new IllegalArgumentException("请输入学期名称");if(repo.findSemester(value)!=null)throw new IllegalArgumentException("此学期已存在，请切换或重命名");JSONObject doc=new JSONObject().put("semester",value).put("startDate",date.getText().toString().trim()).put("totalWeeks",Integer.parseInt(weeks.getText().toString())).put("courses",new JSONArray());save(doc);});}
    public void courses(){try{JSONArray courses=repo.read().getJSONArray("courses");String[] names=new String[courses.length()+1];for(int i=0;i<courses.length();i++){JSONObject c=courses.getJSONObject(i);names[i]=c.optString("name")+" · 周"+"一二三四五六日".charAt(c.optInt("weekday")-1)+" 第"+c.optInt("startPeriod")+"–"+c.optInt("endPeriod")+"节";}names[courses.length()]="＋ 添加课程";new AlertDialog.Builder(a).setTitle("管理课程").setItems(names,(d,i)->editCourse(i==courses.length()?null:courses.optJSONObject(i))).setNegativeButton("关闭",null).show();}catch(Exception e){error(e);}}
    public void editCourse(JSONObject original){try{JSONObject doc=repo.read(),c=original==null?new JSONObject():new JSONObject(original.toString());final AlertDialog[] editor={null};LinearLayout f=form();EditText name=field(f,"课程名称",c.optString("name"),"必填");EditText teacher=field(f,"教师",c.optString("teacher"),"选填");EditText room=field(f,"教室",c.optString("room"),"选填");Spinner day=spinner(f,"星期",new String[]{"周一","周二","周三","周四","周五","周六","周日"},c.optInt("weekday",1)-1);
        EditText start=field(f,"开始节次",String.valueOf(c.optInt("startPeriod",1)),"1–16"),end=field(f,"结束节次",String.valueOf(c.optInt("endPeriod",2)),"1–16");start.setInputType(2);end.setInputType(2);String weekValue="1-"+doc.optInt("totalWeeks",20);JSONArray existing=c.optJSONArray("weeks");if(existing!=null){StringBuilder text=new StringBuilder();for(int i=0;i<existing.length();i++){if(i>0)text.append(",");text.append(existing.optInt(i));}weekValue=text.toString();}else if(original!=null)weekValue=c.optInt("startWeek",1)+"-"+c.optInt("endWeek",20);
        EditText weeks=field(f,"上课周次",weekValue,"如：1-8,10,12-16");Spinner parity=spinner(f,"单双周",new String[]{"每周","单周","双周"},"odd".equals(c.optString("parity"))?1:"even".equals(c.optString("parity"))?2:0);EditText note=field(f,"备注",c.optString("note"),"选填");
        if(original!=null){TextView hint=CampusUi.text(a,"修改会影响这门课程的所有周次；单次调整请使用调课。",12,CampusUi.MUTED);hint.setPadding(0,dp(12),0,0);f.addView(hint);Button delete=CampusUi.button(a,"删除这门课程",false,v->new AlertDialog.Builder(a).setTitle("删除课程？").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{try{JSONArray all=doc.getJSONArray("courses"),next=new JSONArray();for(int i=0;i<all.length();i++)if(!all.getJSONObject(i).optString("id").equals(c.optString("id")))next.put(all.getJSONObject(i));JSONArray deleted=doc.optJSONArray("deletedCourseIds");if(deleted==null)deleted=new JSONArray();deleted.put(c.optString("id"));doc.put("deletedCourseIds",deleted).put("courses",next);save(doc);if(editor[0]!=null)editor[0].dismiss();refresh.run();Toast.makeText(a,"课程已删除",Toast.LENGTH_SHORT).show();}catch(Exception e){error(e);}}).show());f.addView(delete);}
        editor[0]=dialog(original==null?"添加课程":"编辑课程",f,"保存",()->{SortedSet<Integer> values=parseWeeks(weeks.getText().toString(),doc.optInt("totalWeeks",20));int filter=parity.getSelectedItemPosition();values.removeIf(w->filter==1&&w%2==0||filter==2&&w%2!=0);if(values.isEmpty())throw new IllegalArgumentException("筛选后没有上课周次");JSONArray actual=new JSONArray();for(int w:values)actual.put(w);c.put("name",name.getText().toString().trim()).put("teacher",teacher.getText().toString().trim()).put("room",room.getText().toString().trim()).put("note",note.getText().toString().trim()).put("weekday",day.getSelectedItemPosition()+1).put("startPeriod",Integer.parseInt(start.getText().toString())).put("endPeriod",Integer.parseInt(end.getText().toString())).put("weeks",actual).put("startWeek",values.first()).put("endWeek",values.last()).put("parity",filter==1?"odd":filter==2?"even":"all").put("origin","manual");if(c.optString("id").isEmpty())c.put("id",UUID.randomUUID().toString());JSONArray all=doc.getJSONArray("courses"),next=new JSONArray();boolean replaced=false;for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);if(item.optString("id").equals(c.optString("id"))){next.put(c);replaced=true;}else next.put(item);}if(!replaced)next.put(c);doc.put("courses",next);save(doc);});
        }catch(Exception e){error(e);}}
    public static SortedSet<Integer> parseWeeks(String text,int max){TreeSet<Integer> set=new TreeSet<>();for(String part:text.replace("，",",").replace("、",",").replace("–","-").replace("周","").replace(" ","").split(",")){if(!part.matches("\\d{1,2}(-\\d{1,2})?"))throw new IllegalArgumentException("周次格式如：1-8,10,12-16");String[] range=part.split("-");int from=Integer.parseInt(range[0]),to=range.length==2?Integer.parseInt(range[1]):from;if(from<1||to<from||to>max)throw new IllegalArgumentException("周次须在1到"+max+"之间");for(int i=from;i<=to;i++)set.add(i);}return set;}
    public void patches(){try{JSONObject doc=repo.read();JSONArray list=doc.optJSONArray("patches");if(list==null)list=new JSONArray();final JSONArray patches=list;String[] labels=new String[patches.length()+1];for(int i=0;i<patches.length();i++){JSONObject p=patches.getJSONObject(i);labels[i]=patchName(p);}labels[patches.length()]="＋ 添加调课";new AlertDialog.Builder(a).setTitle("调课与停课（按顺序执行）").setItems(labels,(d,i)->{if(i==patches.length())newPatch(doc);else new AlertDialog.Builder(a).setTitle(labels[i]).setMessage("撤销此记录后，课程将按其余调课记录重新计算。").setNegativeButton("保留",null).setPositiveButton("撤销调课",(x,w)->{try{patches.remove(i);doc.put("patches",patches);save(doc);refresh.run();}catch(Exception e){error(e);}}).show();}).setNegativeButton("关闭",null).show();}catch(Exception e){error(e);}}
    private String patchName(JSONObject p){String kind=p.optString("kind"),title=kind.equals("remove")?"停课":kind.equals("copy")?"补课":kind.equals("move")?"移课":"交换";String from="第"+p.optInt("week")+"周周"+"一二三四五六日".charAt(p.optInt("day")-1);return title+" · "+from+(kind.equals("remove")?"":" 至 第"+p.optInt("targetWeek")+"周周"+"一二三四五六日".charAt(p.optInt("targetDay")-1));}
    private void newPatch(JSONObject doc){LinearLayout f=form();Spinner kind=spinner(f,"调整类型",new String[]{"停课：移除当天课程","补课：复制到目标日期","移课：移至目标日期","交换：对调两天课程"},0);EditText week=field(f,"原教学周","1","1–"+doc.optInt("totalWeeks",20));Spinner day=spinner(f,"原星期",new String[]{"周一","周二","周三","周四","周五","周六","周日"},0);EditText target=field(f,"目标教学周（停课无需填写）","1","教学周");Spinner td=spinner(f,"目标星期",new String[]{"周一","周二","周三","周四","周五","周六","周日"},5);dialog("添加调课",f,"保存",()->{JSONObject p=new JSONObject().put("kind",new String[]{"remove","copy","move","swap"}[kind.getSelectedItemPosition()]).put("week",Integer.parseInt(week.getText().toString())).put("day",day.getSelectedItemPosition()+1);if(kind.getSelectedItemPosition()!=0)p.put("targetWeek",Integer.parseInt(target.getText().toString())).put("targetDay",td.getSelectedItemPosition()+1);JSONArray list=doc.optJSONArray("patches");if(list==null)list=new JSONArray();list.put(p);doc.put("patches",list);save(doc);});}
    public void times(){try{JSONObject doc=repo.read();JSONArray current=doc.optJSONArray("periodTimes");StringBuilder text=new StringBuilder();if(current!=null)for(int i=0;i<current.length();i++){if(i>0)text.append("\n");text.append(current.getJSONObject(i).getString("start")).append('-').append(current.getJSONObject(i).getString("end"));}LinearLayout f=form();TextView note=CampusUi.text(a,"每行一节，按第1节起依次填写。以学校作息为准；用于日视图、日历导出和课前提醒。",13,CampusUi.MUTED);f.addView(note);EditText input=field(f,"每节课起止时间",text.toString(),"格式：HH:mm-HH:mm");input.setSingleLine(false);input.setMinLines(5);input.setMaxLines(16);dialog("上课时间",f,"保存",()->{JSONArray times=new JSONArray();String value=input.getText().toString().trim();if(!value.isEmpty())for(String line:value.split("\\n")){String[] parts=line.trim().split("[-–]");if(parts.length!=2)throw new IllegalArgumentException("每行格式为 HH:mm-HH:mm");times.put(new JSONObject().put("start",parts[0].trim()).put("end",parts[1].trim()));}doc.put("periodTimes",times);save(doc);});}catch(Exception e){error(e);}}
    public void reminders(){new AlertDialog.Builder(a).setTitle("课前提醒").setItems(new String[]{"关闭","上课时","提前5分钟","提前10分钟","提前15分钟","提前30分钟"},(d,i)->{try{JSONObject doc=repo.read();if(i>0&&(doc.optString("startDate").isEmpty()||doc.optJSONArray("periodTimes")==null||doc.optJSONArray("periodTimes").length()==0))throw new IllegalArgumentException("请先设置开学日期及上课时间");doc.put("reminderMinutes",new int[]{-1,0,5,10,15,30}[i]);save(doc);if(i>0&&Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},404);Toast.makeText(a,i==0?"课前提醒已关闭":"已设置提醒，可能受系统省电策略影响",Toast.LENGTH_LONG).show();}catch(Exception e){error(e);}}).show();}
    public void appearance(){new AlertDialog.Builder(a).setTitle("课表外观").setItems(new String[]{"课程卡片配色","课程卡片透明度","周末显示方式","选择课表壁纸","移除壁纸","上课状态面板"},(d,i)->{try{
        if(i==0)new AlertDialog.Builder(a).setTitle("课程配色").setItems(new String[]{"湖绿与柔彩","清透蓝","暖杏"},(x,w)->{try{JSONObject doc=repo.read();doc.put("palette",new String[]{"default","blue","apricot"}[w]);save(doc);refresh.run();}catch(Exception e){error(e);}}).show();
        if(i==1){LinearLayout f=form();SeekBar alpha=new SeekBar(a);alpha.setMax(205);alpha.setProgress(repo.read().optInt("cardAlpha",255)-50);TextView hint=CampusUi.text(a,"拖动滑杆调整课程卡片不透明度。",13,CampusUi.MUTED);f.addView(hint);f.addView(alpha,new LinearLayout.LayoutParams(-1,dp(60)));dialog("卡片透明度",f,"保存",()->{JSONObject doc=repo.read();doc.put("cardAlpha",alpha.getProgress()+50);save(doc);});}
        if(i==2)new AlertDialog.Builder(a).setTitle("周末显示方式").setItems(new String[]{"始终显示周六和周日","隐藏无课周末（随本周课程变化）","仅显示周一至周五"},(x,w)->{try{JSONObject doc=repo.read();doc.put("visibleDays",w==2?5:7).put("smartWeekend",w==1);save(doc);refresh.run();}catch(Exception e){error(e);}}).show();
        if(i==3)a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),WALLPAPER);
        if(i==4){JSONObject doc=repo.read();doc.remove("wallpaper");save(doc);refresh.run();}
        if(i==5){JSONObject doc=repo.read();boolean enabled=!doc.optBoolean("showStatus",false);doc.put("showStatus",enabled);save(doc);refresh.run();Toast.makeText(a,enabled?"上课状态面板已开启":"上课状态面板已关闭",Toast.LENGTH_SHORT).show();}
        }catch(Exception e){error(e);}}).show();}
    public void share(View timetable){new AlertDialog.Builder(a).setTitle("分享与备份").setItems(new String[]{"分享周课表图片","分享 iCal 日历","保存 iCal 文件","导出当前课表备份","从备份恢复课表"},(d,i)->{try{JSONObject doc=repo.read();if(i==0){int width=timetable.getWidth(),height=timetable.getHeight();if(width<1||height<1)throw new IllegalArgumentException("请先打开周课表");float scale=Math.min(1f,2400f/Math.max(width,height));Bitmap image=Bitmap.createBitmap(Math.round(width*scale),Math.round(height*scale),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(image);c.scale(scale,scale);timetable.draw(c);ByteArrayOutputStream out=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.PNG,100,out);image.recycle();TimetableShare.send(a,out.toByteArray(),".png","image/png");}if(i==1)TimetableShare.send(a,TimetableModel.ical(doc).getBytes("UTF-8"),".ics","text/calendar");if(i==2)export(TimetableModel.ical(doc),"text/calendar","心心相应课表.ics");if(i==3)export(doc.toString(2),"application/json","心心相应课表备份.json");if(i==4)a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),RESTORE);}catch(Exception e){error(e);}}).show();}
    private void export(String data,String mime,String name){pendingExport=data;a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(mime).putExtra(Intent.EXTRA_TITLE,name).addCategory(Intent.CATEGORY_OPENABLE),EXPORT);}
    public void result(int request,int code,Intent data){if(code!=Activity.RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(request==EXPORT){if(pendingExport==null)throw new IllegalArgumentException("导出已中断，请重新操作");try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("文件无法写入");out.write(pendingExport.getBytes("UTF-8"));}pendingExport=null;Toast.makeText(a,"课表文件已保存",Toast.LENGTH_SHORT).show();}if(request==WALLPAPER){a.getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);JSONObject doc=repo.read();doc.put("wallpaper",uri.toString());save(doc);refresh.run();}if(request==RESTORE){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("文件无法读取");byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>3000000)throw new IOException("备份文件过大");out.write(b,0,n);}}JSONObject doc=new JSONObject(out.toString("UTF-8"));JSONArray courses=doc.getJSONArray("courses");new AlertDialog.Builder(a).setTitle("恢复课表？").setMessage(doc.optString("semester","未命名学期")+"\n共"+courses.length()+"项课程；将保存到当前学校身份。相同学期会替换本机课表。").setNegativeButton("取消",null).setPositiveButton("恢复",(d,w)->{try{doc.put("studentType",a.getSharedPreferences("school_profile",0).getBoolean("postgraduate",false)?"pg":"ug");doc.remove("timetableId");doc.remove("wallpaper");save(doc);refresh.run();}catch(Exception e){error(e);}}).show();}}catch(Exception e){error(e);}}
}
